 await p.eval("window.actualNow=Date.now;Date.now=()=>window.actualNow()+301000;window.dispatchEvent(new Event('focus'))");await p.until("!!document.querySelector('.auth-view')");assert.equal(await p.eval("document.querySelectorAll('.labels-picker-popup,.color-picker-popup,.card-menu-popup,.confirm-dialog').length"),0);assert.equal(await p.eval("(await import('./js/app.js')).getNotes().length"),0);assert.match(await p.eval("document.querySelector('#login-error').textContent"),/expired/i);await p.eval("Date.now=window.actualNow;document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}))");await unlock(p);await p.eval("document.querySelector('#lock-btn').click()");await p.until("!!document.querySelector('.auth-view')");await p.eval("document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}))");assert.deepEqual(p.errors,[]);await p.close();
