scenario('review: conflict copy uses current draft and leaves an unrelated editor open',async({browser,assert})=>{
 const a=await browser.page();await create(a);await add(a,'Shared','Original');const b=await browser.page(a.contextId);await unlock(b);
 await a.eval("document.querySelector('.note-card').click()");await a.until("!!document.querySelector('#modal-editor')");await b.eval("const app=await import('./js/app.js');await app.saveNote({...app.getNotes()[0],content:'Remote'})");await a.eval("document.querySelector('#modal-editor').value='First draft';document.querySelector('#modal-editor').dispatchEvent(new Event('input'));document.querySelector('#modal-close').click()");await a.until("!!document.querySelector('.toast-action')");await a.eval("document.querySelector('#modal-editor').value='Latest draft';document.querySelector('#modal-editor').dispatchEvent(new Event('input'));document.querySelector('.toast-action').click()");await a.until("(await import('./js/app.js')).getNotes().length===2");assert.ok(await a.eval("(await import('./js/app.js')).getNotes().some(n=>n.content==='Latest draft')"));
 await a.until("!document.querySelector('#modal-overlay').classList.contains('open')");await add(a,'Unrelated','Y saved');const sharedId=await b.eval("(await import('./js/app.js')).getNotes().find(n=>n.content==='Remote').id");await a.eval(`document.querySelector('[data-id="${sharedId}"] [data-action=color]').click()`);await b.until("(await import('./js/app.js')).getNotes().length===3");await b.eval("const app=await import('./js/app.js');const n=app.getNotes().find(n=>n.content==='Remote');await app.saveNote({...n,content:'Remote again'})");await a.until("(await import('./js/app.js')).getNotes().some(n=>n.content==='Remote again')");await a.eval("document.querySelector('.color-picker-popup [data-color=mint]').click()");await a.until("!!document.querySelector('.toast-action')");await a.eval("[...document.querySelectorAll('.note-card')].find(c=>c.textContent.includes('Unrelated')).click()");await a.until("!!document.querySelector('#modal-editor')");await a.eval("document.querySelector('#modal-editor').value='Y pending text';document.querySelector('#modal-editor').dispatchEvent(new Event('input'));document.querySelector('.toast-action').click()");await new Promise(r=>setTimeout(r,150));assert.equal(await a.eval("document.querySelector('#modal-editor')?.value"),'Y pending text');assert.equal(await a.eval("document.querySelector('#modal-overlay').classList.contains('open')"),true);await b.close();await a.close();
});
scenario('review: unreadable records remain exportable and recovery is read-only',async({browser,assert})=>{
 const p=await browser.page();await create(p);await add(p);await p.eval("window.confirm=()=>true;await(await import('./js/db.js')).saveNoteRecord({id:crypto.randomUUID(),iv:'AAAA',ciphertext:'AAAA',updatedAt:1})");const before=await p.eval("JSON.stringify(await(await import('./js/db.js')).getAllNoteRecords())");
 const exported=await p.eval("(async()=>{let blob;const old=URL.createObjectURL;URL.createObjectURL=b=>{blob=b;return old(b)};try{await(await import('./js/backup.js')).exportBackup();return (await import('./js/crypto.js')).arrayToBase64(new Uint8Array(await blob.arrayBuffer()))}finally{URL.createObjectURL=old}})()");assert.equal(await p.eval(`JSON.stringify((await(await import('./js/backup-v2.js')).decodeV2((await import('./js/crypto.js')).base64ToArray(${JSON.stringify(exported)}),${JSON.stringify(PASSWORD)})).payload.notes)`),before);
 await p.eval(`const a=await import('./js/app.js'),c=await import('./js/crypto.js'),d=await import('./js/db.js');const n={...${JSON.stringify(note())},content:'z'.repeat(2097500)};const {iv,ciphertext}=await c.encrypt(a.getCryptoKey(),JSON.stringify(n));await d.saveNoteRecord({id:n.id,iv:c.arrayToBase64(iv),ciphertext:c.arrayBufferToBase64(ciphertext),updatedAt:n.updatedAt})`);const archive=await p.eval("(async()=>{let blob;const old=URL.createObjectURL;URL.createObjectURL=b=>{blob=b;return old(b)};try{await(await import('./js/backup.js')).exportBackup();return (await import('./js/crypto.js')).arrayToBase64(new Uint8Array(await blob.arrayBuffer()))}finally{URL.createObjectURL=old}})()");assert.equal(await p.eval(`(await(await import('./js/backup-v2.js')).decodeV2((await import('./js/crypto.js')).base64ToArray(${JSON.stringify(archive)}),${JSON.stringify(PASSWORD)})).payload.notes.length`),3);
 const digest=await p.eval("await(await import('./js/backup-v2.js')).payloadHash(JSON.stringify(await(await import('./js/db.js')).readVault()))");assert.equal(await p.eval(`(async()=>{try{await(await import('./js/backup.js')).importBackup(new File([(await import('./js/crypto.js')).base64ToArray(${JSON.stringify(archive)})],'archive.keeplocal'),${JSON.stringify(PASSWORD)});return false}catch{return true}})()`),true);assert.equal(await p.eval("await(await import('./js/backup-v2.js')).payloadHash(JSON.stringify(await(await import('./js/db.js')).readVault()))"),digest);
 await p.reload();await unlock(p);await p.until("!!document.querySelector('#recover-notes-btn')");await p.eval("document.querySelector('#recover-notes-btn').click()");await p.until("!!document.querySelector('#recovery-content')");await p.eval("document.querySelector('.recovery-record[data-reason=limit]').click()");await p.until("document.querySelector('#recovery-content').value.includes('zzzzzz')");assert.equal(await p.eval("document.querySelector('#recovery-content').readOnly"),true);assert.equal(await p.eval("document.querySelector('#recovery-copy').disabled"),true);await p.eval("document.querySelector('#lock-btn').click()");await p.until("!!document.querySelector('.auth-view')");assert.equal(await p.eval("document.body.textContent.includes('zzzzzz')||!!document.querySelector('#recovery-content')"),false);await p.close();
});
scenario('review: export cancelled by lock cannot download or update lineage',async({browser,assert})=>{
 const p=await browser.page();await create(p);await add(p);const before=await p.eval("JSON.stringify(await(await import('./js/db.js')).readVault())");
 await p.eval("window.exportClicks=0;HTMLAnchorElement.prototype.click=function(){window.exportClicks++};window.originalEncrypt=crypto.subtle.encrypt.bind(crypto.subtle);crypto.subtle.encrypt=async(...args)=>{if(new TextDecoder().decode(args[2]).includes('\\\"manifest\\\"'))await new Promise(resolve=>window.resumeExport=resolve);return window.originalEncrypt(...args)};window.exportResult=(await import('./js/backup.js')).exportBackup().then(()=>false,()=>true);void 0");await p.until("typeof window.resumeExport==='function'");await p.eval("document.querySelector('#lock-btn').click()");await p.until("!!document.querySelector('.auth-view')");await p.eval("crypto.subtle.encrypt=window.originalEncrypt;window.resumeExport()");assert.equal(await p.eval('window.exportResult'),true);assert.equal(await p.eval('window.exportClicks'),0);assert.equal(await p.eval("JSON.stringify(await(await import('./js/db.js')).readVault())"),before);assert.deepEqual(p.errors,[]);await p.close();
});
scenario('review: failed lock asks before discarding unsaved drafts',async({browser,assert})=>{
 const p=await browser.page();await create(p);await add(p);await p.eval("document.querySelector('.note-card').click()");await p.until("!!document.querySelector('#modal-editor')");await p.eval("document.querySelector('#modal-editor').value='Keep or discard explicitly';document.querySelector('#modal-editor').dispatchEvent(new Event('input'));window.originalPut=IDBObjectStore.prototype.put;IDBObjectStore.prototype.put=function(value,...args){if(this.name==='notes')throw Error('injected save failure');return window.originalPut.call(this,value,...args)};window.confirm=()=>false;document.querySelector('#lock-btn').click()");await p.until("!!document.querySelector('.toast')");assert.equal(await p.eval("document.querySelector('#modal-editor').value"),'Keep or discard explicitly');assert.equal(await p.eval("!!document.querySelector('.app-view')"),true);await p.eval("window.confirm=()=>true;document.querySelector('#lock-btn').click()");await p.until("!!document.querySelector('.auth-view')");assert.equal(await p.eval("await(await import('./js/session.js')).getSessionKey()"),null);assert.deepEqual(p.errors,[]);await p.close();
});
scenario('review: an old caller cannot resurrect a permanently deleted record',async({browser,assert})=>{
 const a=await browser.page();await create(a);await add(a);await a.eval("window.oldNote=structuredClone((await import('./js/app.js')).getNotes()[0])");const b=await browser.page(a.contextId);await unlock(b);await b.eval("const app=await import('./js/app.js');const n=app.getNotes()[0];n.deletedAt=Date.now();await app.saveNote(n);await app.permanentDeleteNote(n.id)");await a.until("(await import('./js/app.js')).getNotes().length===0");assert.equal(await a.eval("(async()=>{try{await(await import('./js/app.js')).saveNote(window.oldNote);return false}catch{return true}})()"),true);assert.equal(await a.eval("(await(await import('./js/db.js')).getAllNoteRecords()).length"),0);await b.close();await a.close();
});
scenario('review: autosave preserves newer metadata and duplicate includes pending text',async({browser,assert})=>{
 const p=await browser.page();await create(p);await add(p);await p.eval("document.querySelector('.note-card').click()");await p.until("!!document.querySelector('#modal-editor')");await p.eval("window.originalEncrypt=crypto.subtle.encrypt.bind(crypto.subtle);let held=false;crypto.subtle.encrypt=async(...args)=>{if(!held){held=true;await new Promise(resolve=>window.resumeSave=resolve)}return window.originalEncrypt(...args)};document.querySelector('#modal-editor').value='Edited content';document.querySelector('#modal-editor').dispatchEvent(new Event('input'));document.querySelector('#modal-editor').dispatchEvent(new FocusEvent('blur'))");await p.until("typeof window.resumeSave==='function'");await p.eval("document.querySelector('#modal-pin').click();crypto.subtle.encrypt=window.originalEncrypt;window.resumeSave()");await p.until("(await import('./js/app.js')).getNotes()[0].pinned===true");await p.eval("document.querySelector('#modal-color-btn').click()");await p.until("!!document.querySelector('.color-picker-popup')");await p.eval("document.querySelector('.color-picker-popup [data-color=coral]').click()");await p.until("(await import('./js/app.js')).getNotes()[0].color==='coral'");assert.equal(await p.eval("(await import('./js/app.js')).getNotes()[0].pinned"),true);
 await p.eval("document.querySelector('#modal-editor').value='Latest duplicate text';document.querySelector('#modal-editor').dispatchEvent(new Event('input'));document.querySelector('#modal-duplicate-btn').click()");await p.until("(await import('./js/app.js')).getNotes().length===2");await p.until("!document.querySelector('#modal-overlay').classList.contains('open')");assert.deepEqual(await p.eval("(await import('./js/app.js')).getNotes().map(n=>n.content)"),['Latest duplicate text','Latest duplicate text']);assert.deepEqual(p.errors,[]);await p.close();
});
scenario('review: labels opened from card menu edit the active note draft',async({browser,assert})=>{
 const p=await browser.page();await create(p);await add(p);await p.eval("document.querySelector('[data-action=more]').click();document.querySelector('.card-menu-popup [data-action=labels]').click()");await p.until("!!document.querySelector('#new-label-input')");await p.eval("document.querySelector('#new-label-input').value='Via menu';document.querySelector('#new-label-input').dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}))");await new Promise(r=>setTimeout(r,150));assert.ok(await p.eval("(await import('./js/app.js')).getNotes()[0].labels.includes('Via menu')"));assert.deepEqual(p.errors,[]);await p.close();
});
scenario('review: todo conflict copy includes pending task text',async({browser,assert})=>{
 const a=await browser.page();await create(a);const n=note({type:'todo',tasks:[{id:crypto.randomUUID(),text:'Existing',done:false,order:0,parentId:null}]});await a.eval(`await(await import('./js/app.js')).saveNote(${JSON.stringify(n)});document.querySelector('#search-clear').click();document.querySelector('.note-card').click()`);await a.until("!!document.querySelector('#add-task-input')");const b=await browser.page(a.contextId);await unlock(b);await b.eval("const app=await import('./js/app.js');await app.saveNote({...app.getNotes()[0],title:'Remote title'})");await a.eval("document.querySelector('#add-task-input').value='Pending unentered task';document.querySelector('#add-task-input').dispatchEvent(new Event('input'));document.querySelector('.todo-checkbox').click()");await a.until("!!document.querySelector('.toast-action')");await a.eval("document.querySelector('.toast-action').click()");await a.until("(await import('./js/app.js')).getNotes().length===2");assert.ok(await a.eval("(await import('./js/app.js')).getNotes().some(n=>n.tasks.some(t=>t.text==='Pending unentered task'))"));await b.close();await a.close();
});
scenario('review: failed refresh retains deletion versions for stale callers',async({browser,assert})=>{
 const a=await browser.page();await create(a);await add(a);await a.eval("window.oldNote=structuredClone((await import('./js/app.js')).getNotes()[0])");const b=await browser.page(a.contextId);await unlock(b);await b.eval("const app=await import('./js/app.js');const n=app.getNotes()[0];n.deletedAt=Date.now();await app.saveNote(n);await app.permanentDeleteNote(n.id)");await a.until("(await import('./js/app.js')).getNotes().length===0");await b.eval("const id=crypto.randomUUID();await(await import('./js/db.js')).saveNoteRecord({id,iv:'AAAA',ciphertext:'AAAA',updatedAt:1});const channel=new BroadcastChannel('keeplocal-vault');channel.postMessage({type:'note-changed',id});channel.close()");await a.until("!!document.querySelector('.unreadable-warning')");assert.equal(await a.eval("(async()=>{try{await(await import('./js/app.js')).saveNote(window.oldNote);return false}catch{return true}})()"),true);assert.equal(await a.eval("(await(await import('./js/db.js')).getAllNoteRecords()).length"),1);await b.close();await a.close();
});
